[hidden] { display: none !important; }
:root { color-scheme: light; --ink: #202c39; --muted: #687887; --paper: #fffdf7; --cream: #f4efe2; --coral: #e77962; --teal: #3d817b; --line: #e8e2d5; --gold: #e4b957; }
* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; padding: 36px 18px; display: grid; place-items: center; background-color: #18232f; background-image: radial-gradient(#344452 1.5px, transparent 1.5px); background-size: 18px 18px; color: var(--ink); font: 16px/1.5 system-ui, -apple-system, "Segoe UI", sans-serif; }
.board { width: min(100%, 720px); padding: clamp(22px, 5vw, 42px); background: var(--paper); border: 3px solid #101a24; border-radius: 8px; box-shadow: 9px 9px 0 #101a24; }
.header { display: flex; gap: 18px; align-items: center; margin-bottom: 28px; }
.pixel-icon { flex: 0 0 58px; width: 58px; height: 58px; display: grid; place-items: center; color: #fffdf7; background: var(--coral); border: 3px solid var(--ink); box-shadow: 4px 4px 0 var(--ink); font-size: 32px; font-weight: 800; }
.eyebrow { margin: 0 0 2px; color: var(--teal); font-size: 13px; font-weight: 800; letter-spacing: .12em; }
h1, h2, p { margin-top: 0; }
h1 { margin-bottom: 3px; font-size: clamp(24px, 5vw, 34px); line-height: 1.2; letter-spacing: -.04em; }
.intro, .subtext { margin: 0; color: var(--muted); }
.panel { padding: 22px; border: 2px solid var(--line); border-radius: 6px; background: #fff; }
.section-heading, .tip-panel, .totals-title { display: flex; justify-content: space-between; align-items: center; gap: 16px; }
h2 { margin: 0; font-size: 20px; letter-spacing: -.02em; }
.badge { padding: 4px 10px; border-radius: 3px; color: #285d58; background: #e3f1eb; font-size: 14px; font-weight: 700; }
.add-form { display: grid; grid-template-columns: minmax(0, 1fr) 138px auto; align-items: end; gap: 12px; margin-top: 18px; }
.field label { display: block; margin-bottom: 6px; font-size: 14px; font-weight: 750; }
input { width: 100%; min-width: 0; height: 46px; padding: 0 12px; border: 2px solid #d9d4ca; border-radius: 4px; color: var(--ink); background: #fff; font: inherit; }
input::placeholder { color: #98a1a6; }
input:focus-visible, button:focus-visible, .person-option input:focus-visible + span { outline: 3px solid var(--gold); outline-offset: 3px; }
.price-input, .tip-input { display: flex; align-items: center; height: 46px; padding-left: 12px; border: 2px solid #d9d4ca; border-radius: 4px; color: var(--muted); }
.price-input input, .tip-input input { height: 42px; padding: 0 8px; border: 0; outline: 0; }
.price-input:focus-within, .tip-input:focus-within { outline: 3px solid var(--gold); outline-offset: 2px; }
.button { min-height: 46px; padding: 0 16px; border: 2px solid var(--ink); border-radius: 4px; color: #fff; background: var(--teal); font: inherit; font-weight: 750; cursor: pointer; transition: transform .12s, box-shadow .12s, background .12s; }
.button:hover { background: #326c67; box-shadow: 3px 3px 0 var(--ink); transform: translate(-1px, -1px); }
.button:active { box-shadow: none; transform: translate(2px, 2px); }
.hint { margin: 9px 0 0; color: var(--muted); font-size: 14px; }
.item-list { display: grid; gap: 10px; margin: 18px 0 0; padding: 0; list-style: none; }
.item-row { padding: 14px; border: 1px solid var(--line); border-radius: 4px; background: #fffdf9; }
.item-top { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin-bottom: 11px; }
.item-title { min-width: 0; overflow-wrap: anywhere; font-weight: 750; }
.item-price { flex: none; font-variant-numeric: tabular-nums; font-weight: 800; }
.remove-button { margin-left: 8px; padding: 3px 7px; border: 1px solid #dbb1a8; border-radius: 3px; color: #914c40; background: #fff7f3; font: inherit; cursor: pointer; }
.remove-button:hover { color: #fff; background: var(--coral); }
.remove-button:active { transform: translateY(1px); }
.item-people { display: flex; flex-wrap: wrap; gap: 8px; }
.person-option { position: relative; cursor: pointer; }
.person-option input { position: absolute; width: 1px; height: 1px; opacity: 0; }
.person-option span { display: inline-flex; align-items: center; gap: 6px; min-height: 36px; padding: 4px 10px; border: 1px solid #d9d4ca; border-radius: 3px; color: #51606b; background: #fff; font-size: 14px; font-weight: 650; }
.person-option span::before { content: ""; width: 14px; height: 14px; border: 1px solid #9aa5a5; border-radius: 2px; background: #fff; }
.person-option input:checked + span { border-color: var(--teal); color: #245d57; background: #e8f3ee; }
.person-option input:checked + span::before { border-color: var(--teal); background: var(--teal); box-shadow: inset 0 0 0 3px #e8f3ee; }
.empty-state { margin: 18px 0 0; padding: 16px; border: 1px dashed #cfc8b9; border-radius: 4px; color: var(--muted); text-align: center; }
.message { min-height: 0; margin: 8px 0 0; color: #a44b3e; font-size: 14px; font-weight: 650; }
.tip-panel { margin-top: 16px; }
.tip-field { width: 118px; flex: 0 0 118px; }
.tip-input { padding: 0 10px; }
.tip-input input { text-align: right; }
.tip-input span { font-weight: 700; }
.totals { margin-top: 20px; padding: 22px; border: 2px solid var(--ink); border-radius: 6px; color: #fffdf7; background: var(--ink); }
.totals-title { justify-content: flex-start; }
.totals-title h2 { font-size: 21px; }
.pixel-spark { color: var(--gold); font-size: 22px; }
.people-totals { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-top: 16px; }
.person-total { padding: 13px; border: 1px solid #465463; border-radius: 4px; background: #293745; }
.person-total span { display: block; color: #c4cdd0; font-size: 14px; }
.person-total strong { display: block; margin-top: 3px; font-size: 22px; font-variant-numeric: tabular-nums; }
.grand-total { display: flex; justify-content: space-between; align-items: baseline; gap: 12px; margin-top: 17px; padding-top: 14px; border-top: 1px solid #465463; font-weight: 700; }
.grand-total strong { color: var(--gold); font-size: 26px; font-variant-numeric: tabular-nums; }
.rounding-note { margin: 4px 0 0; color: #c4cdd0; font-size: 13px; }
footer { margin-top: 20px; color: var(--muted); font-size: 14px; text-align: center; }
footer span { color: var(--coral); }
@media (max-width: 520px) { body { padding: 16px 12px; } .board { padding: 22px 16px; box-shadow: 5px 5px 0 #101a24; } .header { gap: 13px; } .pixel-icon { flex-basis: 48px; width: 48px; height: 48px; font-size: 27px; } .panel, .totals { padding: 17px 14px; } .add-form { grid-template-columns: minmax(0, 1fr) 112px; } .item-name-field { grid-column: 1 / -1; } .add-button { grid-column: 1 / -1; } .people-totals { gap: 6px; } .person-total { padding: 10px 7px; } .person-total strong { font-size: 18px; } }

const people = ['Alex', 'Blair', 'Casey'];
const items = [];
const form = document.querySelector('#item-form');
const nameInput = document.querySelector('#item-name');
const priceInput = document.querySelector('#item-price');
const tipInput = document.querySelector('#tip-percent');
const list = document.querySelector('#item-list');
const emptyState = document.querySelector('#empty-state');
const message = document.querySelector('#form-message');
const totals = document.querySelector('#people-totals');
const grandTotal = document.querySelector('#grand-total');
const money = cents => `$${(cents / 100).toFixed(2)}`;

function renderItems() {
  list.replaceChildren();
  emptyState.hidden = items.length > 0;
  items.forEach((item, index) => {
    const row = document.createElement('li');
    row.className = 'item-row';
    const top = document.createElement('div');
    top.className = 'item-top';
    const title = document.createElement('span');
    title.className = 'item-title';
    title.textContent = item.name;
    const right = document.createElement('div');
    right.className = 'item-price';
    right.append(document.createTextNode(money(item.cents)));
    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'remove-button';
    remove.textContent = 'Remove';
    remove.setAttribute('aria-label', `Remove ${item.name}`);
    remove.addEventListener('click', () => { items.splice(index, 1); renderItems(); renderTotals(); });
    right.append(remove);
    top.append(title, right);
    const choices = document.createElement('div');
    choices.className = 'item-people';
    choices.setAttribute('role', 'group');
    choices.setAttribute('aria-label', `Who shared ${item.name}?`);
    people.forEach((person, personIndex) => {
      const label = document.createElement('label');
      label.className = 'person-option';
      const checkbox = document.createElement('input');
      checkbox.type = 'checkbox';
      checkbox.checked = item.shared.includes(personIndex);
      checkbox.setAttribute('aria-label', `${person} shared ${item.name}`);
      checkbox.addEventListener('change', () => {
        if (checkbox.checked) item.shared.push(personIndex);
        else item.shared = item.shared.filter(value => value !== personIndex);
        renderTotals();
      });
      const text = document.createElement('span');
      text.textContent = person;
      label.append(checkbox, text);
      choices.append(label);
    });
    row.append(top, choices);
    list.append(row);
  });
}

function renderTotals() {
  const base = [0, 0, 0];
  for (const item of items) {
    if (!item.shared.length) continue;
    const share = item.cents / item.shared.length;
    item.shared.forEach(person => { base[person] += share; });
  }
  const tipValue = Number(tipInput.value);
  const tipPercent = Number.isFinite(tipValue) ? Math.max(0, Math.min(100, tipValue)) : 0;
  const owed = base.map(value => Math.round(value * (1 + tipPercent / 100)));
  totals.replaceChildren();
  people.forEach((person, index) => {
    const card = document.createElement('div');
    card.className = 'person-total';
    const label = document.createElement('span');
    label.textContent = person;
    const amount = document.createElement('strong');
    amount.textContent = money(owed[index]);
    card.append(label, amount);
    totals.append(card);
  });
  grandTotal.textContent = money(owed.reduce((sum, value) => sum + value, 0));
}

form.addEventListener('submit', event => {
  event.preventDefault();
  const name = nameInput.value.trim();
  const price = Number(priceInput.value);
  if (!name || !Number.isFinite(price) || price <= 0) return;
  items.push({ name, cents: Math.round(price * 100), shared: [0, 1, 2] });
  message.textContent = '';
  form.reset();
  renderItems();
  renderTotals();
  nameInput.focus();
});
tipInput.addEventListener('input', renderTotals);
renderItems();
renderTotals();
